head.b:skin:
/*
Name: JHF LAPTOP ZONE Ultimate Blogger Template & Admin Suite
Designer: Jahid Hasan Firoz (JHF LAPTOP ZONE)
URL: https://www.jhflaptopzone.com/
Admin ID: jhflaptopzone@gmail.com
Contact: +88 01935 69 30 71 / +88 01731 69 30 71
Version: 4.0.0
*/

:root {
  --primary: #0f172a;
  --primary-dark: #020617;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --accent-light: #eff6ff;
  --background: #f8fafc;
  --surface: #ffffff;
  --surface-alt: #f1f5f9;
  --text: #0f172a;
  --text-muted: #64748b;
  --border: #e2e8f0;
  --border-light: #f1f5f9;
  --success: #16a34a;
  --warning: #f59e0b;
  --danger: #ef4444;
  --shadow-sm: 0 1px 3px 0 rgba(0,0,0,0.06);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.08), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.05);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.15);
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --container: 1240px;
  --header-height: 70px;
}

[data-theme='dark'] {
  --primary: #f8fafc;
  --primary-dark: #ffffff;
  --accent: #3b82f6;
  --accent-hover: #60a5fa;
  --accent-light: #1e293b;
  --background: #090d16;
  --surface: #111827;
  --surface-alt: #1f2937;
  --text: #f3f4f6;
  --text-muted: #9ca3af;
  --border: #1f2937;
  --border-light: #374151;
  --shadow-sm: 0 1px 3px 0 rgba(0,0,0,0.4);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.5);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.6);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body {
  font-family: 'Inter', 'Hind Siliguri', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--background);
  color: var(--text);
  line-height: 1.6;
  transition: background-color 0.25s ease, color 0.25s ease;
  overflow-x: hidden;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
.container { max-width: var(--container); margin: 0 auto; padding: 0 20px; }

/* SVG Icon Helper */
.jhf-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}
.jhf-icon svg {
  width: 100%;
  height: 100%;
  fill: currentColor;
}
.jhf-icon-stroke svg {
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Top Bar */
.topbar { background: var(--primary-dark); color: #cbd5e1; font-size: 13px; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,0.08); }
.topbar-inner { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; }
.topbar-contact { display: flex; gap: 18px; align-items: center; }
.topbar-contact a { display: flex; align-items: center; gap: 6px; color: #cbd5e1; font-weight: 500; }
.topbar-contact a:hover { color: #38bdf8; }
.topbar-badge { background: #2563eb; color: #fff; font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: var(--radius-full); }

/* Header */
.header { position: sticky; top: 0; z-index: 100; background: var(--surface); border-bottom: 1px solid var(--border); height: var(--header-height); display: flex; align-items: center; box-shadow: var(--shadow-sm); }
.header-inner { display: flex; justify-content: space-between; align-items: center; width: 100%; }
.logo { font-size: 20px; font-weight: 800; color: var(--primary); letter-spacing: -0.5px; display: flex; align-items: center; gap: 8px; }
.logo-badge { background: var(--accent); color: #fff; font-size: 11px; font-weight: 700; padding: 3px 7px; border-radius: var(--radius-sm); letter-spacing: 0.5px; }

/* Navigation */
.nav-desktop { display: flex; align-items: center; gap: 16px; list-style: none; }
.nav-desktop a { font-size: 13.5px; font-weight: 600; color: var(--text-muted); padding: 6px 10px; border-radius: var(--radius); transition: all 0.15s; }
.nav-desktop a:hover { color: var(--accent); background: var(--accent-light); }
.header-actions { display: flex; align-items: center; gap: 8px; }

/* Buttons */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; padding: 8px 16px; border-radius: var(--radius); font-size: 13.5px; font-weight: 600; cursor: pointer; transition: all 0.2s ease; border: 1px solid transparent; white-space: nowrap; }
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover { background: var(--accent-hover); color: #fff; }
.btn-whatsapp { background: #25D366; color: #fff; }
.btn-whatsapp:hover { background: #20ba5a; color: #fff; }
.btn-admin { background: #0f172a; color: #f8fafc; border: 1px solid #334155; }
.btn-admin:hover { background: #1e293b; color: #38bdf8; border-color: #38bdf8; }
.btn-outline { border-color: var(--border); color: var(--text); background: var(--surface); }
.btn-outline:hover { background: var(--surface-alt); border-color: var(--text-muted); }
.btn-icon { width: 38px; height: 38px; padding: 0; border-radius: var(--radius); }
.btn-sm { padding: 6px 12px; font-size: 12.5px; }

/* Hero Section */
.hero-section { padding: 40px 0 30px; text-align: center; }
.hero-badge { display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px; border-radius: var(--radius-full); background: var(--accent-light); color: var(--accent); font-size: 13px; font-weight: 700; margin-bottom: 20px; border: 1px solid rgba(37,99,235,0.2); }
.hero-title { font-size: 38px; font-weight: 800; color: var(--text); line-height: 1.2; margin-bottom: 16px; letter-spacing: -0.5px; }
.hero-title span { color: var(--accent); }
.hero-subtitle { font-size: 17px; color: var(--text-muted); max-width: 780px; margin: 0 auto 28px; line-height: 1.6; }
.hero-ctas { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-bottom: 36px; }

/* Trust Highlights Grid */
.trust-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 40px; }
.trust-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px 16px; display: flex; align-items: center; gap: 14px; box-shadow: var(--shadow-sm); }
.trust-card-icon { width: 44px; height: 44px; border-radius: var(--radius); background: var(--accent-light); color: var(--accent); display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 20px; }
.trust-card-title { font-size: 14px; font-weight: 700; color: var(--text); }
.trust-card-desc { font-size: 12px; color: var(--text-muted); }

/* Product Cards Grid */
.product-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; }
.product-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; display: flex; flex-direction: column; transition: transform 0.2s, box-shadow 0.2s; box-shadow: var(--shadow-sm); }
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); border-color: var(--accent); }
.product-thumb-wrap { position: relative; width: 100%; padding-top: 68%; background: var(--surface-alt); overflow: hidden; }
.product-thumb { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; }
.product-badge { position: absolute; top: 10px; left: 10px; background: rgba(15,23,42,0.85); color: #fff; font-size: 11px; font-weight: 700; padding: 3px 8px; border-radius: 4px; backdrop-filter: blur(4px); }
.product-info { padding: 16px; display: flex; flex-direction: column; flex-grow: 1; }
.product-cat { font-size: 11px; font-weight: 700; color: var(--accent); text-transform: uppercase; margin-bottom: 4px; }
.product-title { font-size: 15px; font-weight: 700; color: var(--text); line-height: 1.4; margin-bottom: 8px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.product-snippet { font-size: 12.5px; color: var(--text-muted); margin-bottom: 14px; line-height: 1.5; flex-grow: 1; }
.product-meta { display: flex; align-items: center; justify-content: space-between; padding-top: 12px; border-top: 1px solid var(--border-light); margin-bottom: 12px; }
.price-ask { font-size: 14px; font-weight: 700; color: var(--accent); }
.product-card-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }

/* Hub Download Cards */
.hub-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 16px; }
.hub-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px; display: flex; flex-direction: column; justify-content: space-between; box-shadow: var(--shadow-sm); transition: all 0.2s; }
.hub-card:hover { border-color: var(--accent); box-shadow: var(--shadow-md); }
.hub-card-cat { font-size: 11px; font-weight: 700; color: var(--accent); text-transform: uppercase; margin-bottom: 4px; }
.hub-card-title { font-size: 15px; font-weight: 700; color: var(--text); margin-bottom: 6px; }
.hub-card-desc { font-size: 12px; color: var(--text-muted); margin-bottom: 12px; line-height: 1.4; flex-grow: 1; }
.hub-card-btn { margin-top: auto; width: 100%; }

/* Section Styling */
.info-block { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 28px; margin-bottom: 32px; box-shadow: var(--shadow-sm); }
.section-title { font-size: 22px; font-weight: 800; color: var(--text); margin-bottom: 6px; }
.section-subtitle { font-size: 14px; color: var(--text-muted); margin-bottom: 20px; }

/* Live Clock */
.clock-wrapper { background: #0f172a; border-radius: var(--radius); padding: 14px; text-align: center; margin-top: 14px; }
.clock-display { color: #38bdf8; font-family: monospace; font-size: 22px; font-weight: 700; letter-spacing: 2px; }

/* Floating Buttons */
.floating-tools { position: fixed; bottom: 24px; right: 24px; display: flex; flex-direction: column; gap: 12px; z-index: 999; }
.float-btn { width: 50px; height: 50px; border-radius: var(--radius-full); display: flex; align-items: center; justify-content: center; box-shadow: var(--shadow-lg); cursor: pointer; transition: transform 0.2s ease; border: none; }
.float-btn:hover { transform: scale(1.08); }
.float-whatsapp { background: #25D366; color: #fff; }
.float-admin { background: #0f172a; color: #38bdf8; border: 2px solid #38bdf8; }
.float-top { background: var(--primary); color: #fff; display: none; }
.float-top.show { display: flex; }

/* In-Page Admin Modal & Panel */
.admin-modal-backdrop { position: fixed; inset: 0; background: rgba(2,6,23,0.8); backdrop-filter: blur(4px); z-index: 10000; display: none; align-items: center; justify-content: center; padding: 16px; }
.admin-modal-backdrop.active { display: flex; }
.admin-modal-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); max-width: 460px; width: 100%; padding: 28px; box-shadow: var(--shadow-xl); position: relative; }
.admin-form-group { margin-bottom: 16px; }
.admin-form-label { display: block; font-size: 12.5px; font-weight: 700; color: var(--text); margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px; }
.admin-form-input { width: 100%; padding: 10px 14px; border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface-alt); color: var(--text); font-size: 14px; outline: none; }
.admin-form-input:focus { border-color: var(--accent); background: var(--surface); }

/* Admin Drawer / Dashboard */
.admin-drawer { position: fixed; top: 0; right: 0; width: 100%; max-width: 600px; height: 100vh; background: var(--surface); border-left: 1px solid var(--border); z-index: 10001; box-shadow: var(--shadow-xl); display: none; flex-direction: column; overflow-y: auto; }
.admin-drawer.active { display: flex; }
.admin-drawer-header { padding: 18px 24px; background: #0f172a; color: #fff; display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #334155; }
.admin-drawer-body { padding: 24px; flex-grow: 1; overflow-y: auto; }
.admin-nav-tabs { display: flex; gap: 8px; border-bottom: 1px solid var(--border); padding-bottom: 12px; margin-bottom: 20px; overflow-x: auto; }
.admin-tab-btn { padding: 7px 14px; font-size: 13px; font-weight: 700; border-radius: var(--radius); border: 1px solid var(--border); background: var(--surface-alt); color: var(--text); cursor: pointer; white-space: nowrap; }
.admin-tab-btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }

/* Footer */
.footer { background: #020617; color: #94a3b8; padding: 56px 0 24px; border-top: 1px solid rgba(255,255,255,0.08); font-size: 14px; margin-top: 40px; }
.footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1.5fr; gap: 36px; margin-bottom: 40px; }
.footer-col-title { color: #f8fafc; font-size: 16px; font-weight: 700; margin-bottom: 18px; }
.footer-links { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-links a:hover { color: #38bdf8; }
.footer-bottom { padding-top: 24px; border-top: 1px solid rgba(255,255,255,0.08); text-align: center; font-size: 13px; color: #64748b; }

/* Responsive */
@media (max-width: 1024px) {
  .trust-grid { grid-template-columns: repeat(2, 1fr); }
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .hub-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 768px) {
  .topbar { display: none; }
  .nav-desktop { display: none; }
  .hero-title { font-size: 30px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
  .trust-grid { grid-template-columns: 1fr; }
  .hub-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .product-grid { grid-template-columns: 1fr; }
  .product-card-actions { grid-template-columns: 1fr; }
}
/* Sales Invoice Modal & Sheet Styles */
.invoice-modal-backdrop { position: fixed; inset: 0; background: rgba(2,6,23,0.85); backdrop-filter: blur(5px); z-index: 10005; display: none; align-items: center; justify-content: center; padding: 20px; overflow-y: auto; }
.invoice-modal-backdrop.active { display: flex; }
.invoice-paper-card { background: #ffffff; color: #000000; border-radius: 8px; width: 100%; max-width: 820px; position: relative; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.5); overflow: hidden; margin: auto; }
.invoice-actions-bar { background: #0f172a; padding: 12px 20px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px; }
.invoice-table { width: 100%; border-collapse: collapse; margin-top: 15px; margin-bottom: 15px; }
.invoice-table th, .invoice-table td { border: 1px solid #000; padding: 6px 10px; font-size: 11.5px; text-align: left; }
.invoice-table th { background: #f1f5f9; font-weight: 800; text-align: center; }

@media print {
  body * { visibility: hidden !important; }
  #sales-invoice-printable, #sales-invoice-printable * { visibility: visible !important; }
  #sales-invoice-printable {
    position: fixed !important;
    left: 0 !important;
    top: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    padding: 12mm 15mm !important;
    box-shadow: none !important;
    border: none !important;
    background: #ffffff !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
    display: block !important;
    z-index: 9999999 !important;
  }
}

head.b:template-skin:
/* Template skin for layout designer */
body#layout {
  width: 100%;
}

body.script:
//
(function() {
  // 1. Dark Mode
  var themeToggle = document.getElementById('themeToggle');
  var currentTheme = localStorage.getItem('jhf_theme') || 'light';
  if (currentTheme === 'dark') {
    document.documentElement.setAttribute('data-theme', 'dark');
  }
  if (themeToggle) {
    themeToggle.addEventListener('click', function() {
      var theme = document.documentElement.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', theme);
      localStorage.setItem('jhf_theme', theme);
    });
  }

  // 2. Back To Top
  var backToTop = document.getElementById('backToTop');
  window.addEventListener('scroll', function() {
    if (window.scrollY > 300) {
      if (backToTop) backToTop.classList.add('show');
    } else {
      if (backToTop) backToTop.classList.remove('show');
    }
  });
  if (backToTop) {
    backToTop.addEventListener('click', function() {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });
  }

  // 3. Live Digital Clock
  var clockEl = document.getElementById('liveDhakaClock');
  if (clockEl) {
    function updateClock() {
      var now = new Date();
      var hours = now.getHours();
      var minutes = now.getMinutes();
      var seconds = now.getSeconds();
      var ampm = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12;
      hours = hours ? hours : 12;
      var strTime = (hours < 10 ? '0' : '') + hours + ':' +
                    (minutes < 10 ? '0' : '') + minutes + ':' +
                    (seconds < 10 ? '0' : '') + seconds + ' ' + ampm;
      clockEl.textContent = strTime;
    }
    updateClock();
    setInterval(updateClock, 1000);
  }

  // 4. In-Page Admin Suite
  var isAuth = localStorage.getItem('jhf_blogger_auth') === 'true';

  var modal = document.getElementById('adminLoginModal');
  var drawer = document.getElementById('adminDrawer');
  var btnOpen1 = document.getElementById('btnOpenAdminModal');
  var btnOpen2 = document.getElementById('btnOpenAdminModalTop');
  var btnOpen3 = document.getElementById('btnFloatAdmin');
  var btnCloseModal = document.getElementById('btnCloseAdminModal');
  var btnCloseDrawer = document.getElementById('btnCloseAdminDrawer');
  var btnLogout = document.getElementById('btnAdminLogout');
  var formLogin = document.getElementById('adminLoginForm');
  var errorEl = document.getElementById('adminLoginError');

  function openAdmin() {
    if (isAuth) {
      if (drawer) drawer.classList.add('active');
    } else {
      if (modal) modal.classList.add('active');
    }
  }

  if (btnOpen1) btnOpen1.addEventListener('click', openAdmin);
  if (btnOpen2) btnOpen2.addEventListener('click', openAdmin);
  if (btnOpen3) btnOpen3.addEventListener('click', openAdmin);

  if (btnCloseModal) btnCloseModal.addEventListener('click', function() {
    if (modal) modal.classList.remove('active');
  });

  if (btnCloseDrawer) btnCloseDrawer.addEventListener('click', function() {
    if (drawer) drawer.classList.remove('active');
  });

  if (btnLogout) btnLogout.addEventListener('click', function() {
    isAuth = false;
    localStorage.removeItem('jhf_blogger_auth');
    if (drawer) drawer.classList.remove('active');
    alert('You have logged out from Admin Panel.');
  });

  if (formLogin) {
    formLogin.addEventListener('submit', function(e) {
      e.preventDefault();
      var u = (document.getElementById('adminLoginUser').value || '').trim().toLowerCase();
      var p = (document.getElementById('adminLoginPass').value || '').trim();

      var isSuperAdmin = (u === 'jhfboss' || u === 'jhflaptopzone@gmail.com' || u === 'jhflaptopzone.com') && p === 'J@#f693071';
      if (isSuperAdmin) {
        isAuth = true;
        localStorage.setItem('jhf_blogger_auth', 'true');
        if (errorEl) errorEl.style.display = 'none';
        var displayEl = document.getElementById('adminDisplayUser');
        if (displayEl) displayEl.textContent = 'jhfboss (Super Admin)';
        if (modal) modal.classList.remove('active');
        if (drawer) drawer.classList.add('active');
      } else {
        if (errorEl) {
          errorEl.textContent = 'Invalid Email or Password! Please verify your admin credentials.';
          errorEl.style.display = 'block';
        }
      }
    });
  }

  // Tab switching inside drawer
  var tabBtns = document.querySelectorAll('.admin-tab-btn');
  tabBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      tabBtns.forEach(function(b) { b.classList.remove('active'); });
      btn.classList.add('active');
      var target = btn.getAttribute('data-tab');
      var panels = ['tab-quick', 'tab-add-item', 'tab-store'];
      panels.forEach(function(p) {
        var el = document.getElementById(p);
        if (el) el.style.display = (p === target) ? 'block' : 'none';
      });
    });
  });

  // Add Item Form
  var formAddItem = document.getElementById('formAddDownloadItem');
  if (formAddItem) {
    formAddItem.addEventListener('submit', function(e) {
      e.preventDefault();
      var sec = document.getElementById('newSectionTarget').value;
      var title = document.getElementById('newDownloadTitle').value;
      var cat = document.getElementById('newDownloadCat').value;
      var link = document.getElementById('newDownloadLink').value;
      var desc = document.getElementById('newDownloadDesc').value;

      var targetGridId = sec === 'testing' ? 'testing-tools' : (sec === 'os' ? 'os-iso-zone' : 'software-zone');
      var targetSection = document.getElementById(targetGridId);
      if (targetSection) {
        var grid = targetSection.querySelector('.hub-grid');
        if (grid) {
          var newCard = document.createElement('div');
          newCard.className = 'hub-card';
          newCard.innerHTML = "<div class='hub-card-cat'>" + cat + "</div>" +
                              "<div class='hub-card-title'>" + title + "</div>" +
                              (desc ? "<div class='hub-card-desc'>" + desc + "</div>" : "") +
                              "<a class='btn btn-outline btn-sm hub-card-btn' href='" + link + "' target='_blank'>Download ↗</a>";
          grid.insertBefore(newCard, grid.firstChild);
          alert('Item added successfully to ' + sec + ' section!');
          formAddItem.reset();
        }
      }
    });
  }

  // 5. Laptop Filter & Search Logic
  var filterBtns = document.querySelectorAll('#laptopFilterBar button');
  var searchInput = document.getElementById('laptopSearchInput');
  var currentBrand = 'all';

  function filterLaptops() {
    var query = (searchInput ? searchInput.value : '').toLowerCase().trim();
    var cards = document.querySelectorAll('#laptopProductGrid .product-card');
    cards.forEach(function(card) {
      var brand = (card.getAttribute('data-brand') || '').toLowerCase();
      var text = (card.innerText || card.textContent || '').toLowerCase();

      var matchesBrand = (currentBrand === 'all') || (brand.indexOf(currentBrand.toLowerCase()) !== -1);
      var matchesQuery = !query || (text.indexOf(query) !== -1);

      if (matchesBrand && matchesQuery) {
        card.style.display = 'flex';
      } else {
        card.style.display = 'none';
      }
    });
  }

  if (filterBtns) {
    filterBtns.forEach(function(b) {
      b.addEventListener('click', function() {
        filterBtns.forEach(function(btn) { btn.classList.remove('active'); });
        b.classList.add('active');
        currentBrand = b.getAttribute('data-filter') || 'all';
        filterLaptops();
      });
    });
  }

  if (searchInput) {
    searchInput.addEventListener('input', filterLaptops);
  }

  // 6. Sales Invoice Modal & Print Logic
  var invoiceModal = document.getElementById('salesInvoiceModal');
  var btnOpenInvoice = document.getElementById('btnOpenInvoiceModal');
  var btnCloseInvoice = document.getElementById('btnCloseInvoiceModal');
  var btnPrintInvoice = document.getElementById('btnPrintInvoice');
  var btnToggleEdit = document.getElementById('btnToggleInvoiceEdit');
  var invoiceEditPanel = document.getElementById('invoiceEditPanel');

  function openInvoiceModal() {
    if (invoiceModal) invoiceModal.classList.add('active');
  }
  function closeInvoiceModal() {
    if (invoiceModal) invoiceModal.classList.remove('active');
  }

  if (btnOpenInvoice) btnOpenInvoice.addEventListener('click', openInvoiceModal);
  if (btnCloseInvoice) btnCloseInvoice.addEventListener('click', closeInvoiceModal);

  if (btnToggleEdit && invoiceEditPanel) {
    btnToggleEdit.addEventListener('click', function() {
      invoiceEditPanel.style.display = (invoiceEditPanel.style.display === 'none' || !invoiceEditPanel.style.display) ? 'block' : 'none';
    });
  }

  if (btnPrintInvoice) {
    btnPrintInvoice.addEventListener('click', function() {
      window.print();
    });
  }

  // Number to words converter for Bangladeshi Taka
  function convertNumberToWords(amount) {
    var words = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
    var tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
    function numToWords(n) {
      if (n < 20) return words[n];
      var digit = n % 10;
      return tens[Math.floor(n / 10)] + (digit ? " " + words[digit] : "");
    }
    if (amount === 0) return "Zero Taka Only";
    var result = "";
    var crore = Math.floor(amount / 10000000); amount %= 10000000;
    var lakh = Math.floor(amount / 100000); amount %= 100000;
    var thousand = Math.floor(amount / 1000); amount %= 1000;
    var hundred = Math.floor(amount / 100); var rem = amount % 100;
    if (crore > 0) result += numToWords(crore) + " Crore ";
    if (lakh > 0) result += numToWords(lakh) + " Lakh ";
    if (thousand > 0) result += numToWords(thousand) + " Thousand ";
    if (hundred > 0) result += numToWords(hundred) + " Hundred ";
    if (rem > 0) result += (result ? "and " : "") + numToWords(rem) + " ";
    return (result.trim() + " Taka Only");
  }

  // Live sync input fields to invoice layout
  function syncInvoiceFields() {
    var cust = document.getElementById('invInpCustomer');
    var phone = document.getElementById('invInpPhone');
    var addr = document.getElementById('invInpAddress');
    var invNo = document.getElementById('invInpInvoiceNo');
    var date = document.getElementById('invInpDate');
    var salesBy = document.getElementById('invInpSalesBy');
    var item = document.getElementById('invInpItemName');
    var serial = document.getElementById('invInpSerial');
    var price = document.getElementById('invInpPrice');
    var opacity = document.getElementById('invInpOpacity');
    var watermark = document.getElementById('invWatermarkDiv');
    var valOpacity = document.getElementById('valOpacity');

    if (cust) document.getElementById('invDspCustomer').textContent = cust.value || 'Valued Customer';
    if (phone) document.getElementById('invDspPhone').textContent = phone.value || 'N/A';
    if (addr) document.getElementById('invDspAddress').textContent = addr.value || 'N/A';
    if (invNo) document.getElementById('invDspInvoiceNo').textContent = invNo.value || 'JHF-INVOICE';
    if (date && date.value) document.getElementById('invDspDate').textContent = date.value;
    if (salesBy) document.getElementById('invDspSalesBy').textContent = salesBy.value || 'Jahid Hasan';
    if (item) document.getElementById('invDspItemName').textContent = item.value || 'Laptop';
    if (serial) document.getElementById('invDspSerial').textContent = 'Serial: ' + (serial.value || 'N/A');

    var pVal = price ? (parseInt(price.value, 10) || 0) : 0;
    var formatted = pVal.toLocaleString('en-US');
    var dspUnitPrice = document.getElementById('invDspUnitPrice');
    var dspAmount = document.getElementById('invDspAmount');
    var dspTotalBox = document.getElementById('invDspTotalBox');
    var dspInWords = document.getElementById('invDspInWords');

    if (dspUnitPrice) dspUnitPrice.textContent = '৳ ' + formatted;
    if (dspAmount) dspAmount.textContent = '৳ ' + formatted;
    if (dspTotalBox) dspTotalBox.textContent = formatted + ' TK';
    if (dspInWords) dspInWords.textContent = convertNumberToWords(pVal);

    if (opacity && watermark) {
      watermark.style.opacity = opacity.value;
      if (valOpacity) valOpacity.textContent = Math.round(parseFloat(opacity.value) * 100) + '%';
    }
  }

  var invInputs = ['invInpCustomer', 'invInpPhone', 'invInpAddress', 'invInpInvoiceNo', 'invInpDate', 'invInpSalesBy', 'invInpItemName', 'invInpSerial', 'invInpPrice', 'invInpOpacity'];
  invInputs.forEach(function(id) {
    var el = document.getElementById(id);
    if (el) {
      el.addEventListener('input', syncInvoiceFields);
      el.addEventListener('change', syncInvoiceFields);
    }
  });

  var dt = document.getElementById('invInpDate');
  if (dt && !dt.value) {
    dt.value = new Date().toISOString().split('T')[0];
    syncInvoiceFields();
  }

  // Keyboard shortcut Ctrl+Shift+A for fast admin access
  document.addEventListener('keydown', function(e) {
    if (e.ctrlKey && e.shiftKey && (e.key === 'A' || e.key === 'a')) {
      e.preventDefault();
      openAdmin();
    }
  });

})();
